import { test, expect, BASE_URL } from '../utils/setup';

test("QA-280: [Automated] Ensure Failed Login Message", async ({ page }) => {
  await test.step('Navigate to login page', async () => {
    await page.goto(`${BASE_URL}/#/login`);
  });

  await test.step('Enter invalid credentials', async () => {
    await page.getByRole('textbox', { name: 'Email' }).fill('fake@email.com');
    await page.getByRole('textbox', { name: 'Password' }).fill('fake');
    await page.getByRole('button', { name: 'Login' }).click();
  });

  await test.step('Verify invalid user error message', async () => {
    await expect(page.locator('form').getByText('Invalid User')).toBeVisible();
  });
});